": "supplier cost collaboration"}, {"id": "0d6a2d65-8f8e-460d-afe7-fb11c16c4d5e", "type": "concept", "title": "kaizen costing"}, {"id": "9bd09267-1d3b-4028-a3e0-16e9f9d3e031", "type": "concept", "title": "launch economics"}], "description": "This section brings cost management into product design and launch decisions."}, {"id": "4757058f-5eee-4730-87e3-20baea6091d3", "type": "subtopic", "title": "Product portfolio decisions", "children": [{"id": "740fc8c5-929c-4a5a-adf3-54b4db51f4f3", "type": "concept", "title": "product mix"}, {"id": "8775241c-a538-4ca0-9763-8371587fad79", "type": "concept", "title": "portfolio margin"}, {"id": "bdff2226-0330-4145-a77e-04015b23ad84", "type": "concept", "title": "cannibalization"}, {"id": "3907b440-217d-441b-b5f4-0fd68f761769", "type": "concept", "title": "cross-subsidy"}, {"id": "ce8b8a03-811f-466e-aea1-c65d5b805cc8", "type": "concept", "title": "loss leader"}, {"id": "c5e2e13b-b4a5-4bd1-bc6a-b3193b537c39", "type": "concept", "title": "SKU rationalization"}, {"id": "7a96392c-083f-43c5-9136-d8731a4d2ec8", "type": "concept", "title": "complexity cost"}, {"id": "ffcbcc73-4573-43c2-a9db-a62407f6dbfb", "type": "concept", "title": "strategic fit"}, {"id": "c1e6c246-d96a-4831-896b-15e262c078e0", "type": "concept", "title": "capacity allocation"}, {"id": "ffdf07c4-00fd-4738-bc8d-5489be93daf8", "type": "concept", "title": "profit pool"}], "description": "Students learn to manage product economics across a portfolio, not one SKU at a time."}]}, {"id": "7eb35018-3563-4025-85aa-9f3876a1e61b", "type": "topic", "title": "Capital Budgeting, Life-Cycle Costing, and Long-Run Decisions", "description": "Extend managerial decision making to multi-period investments, total cost of ownership, and strategic capacity. Incorporate cash flows, risk, taxes, operating costs, and life-cycle economics into long-run decisions.", "children": [{"id": "ff64c00a-c714-4bc9-8f36-51205a4e13a0", "type": "subtopic", "title": "Capital budgeting metrics", "children": [{"i