update public.learning_paths
set
  title = 'Cost/Managerial Accounting',
  goal = 'Cost/Managerial Accounting',
  summary = 'The sequence is designed for a 15-16 week graduate accounting course. It moves from cost concepts and cost behavior through costing systems, CVP, budgeting, variance, decision models, transfer pricing, performance measurement, lean and process metrics, analytics, ethics, and a capstone decision memo.',
  data = $cmacjson${"slug": "cost-managerial-accounting", "title": "Cost/Managerial Accounting", "description": "The sequence is designed for a 15-16 week graduate accounting course. It moves from cost concepts and cost behavior through costing systems, CVP, budgeting, variance, decision models, transfer pricing, performance measurement, lean and process metrics, analytics, ethics, and a capstone decision memo.", "topics": [{"id": "2f9dddaf-555f-469b-8813-be65f3576a79", "type": "topic", "title": "Managerial Accounting as a Decision System", "description": "Frame cost accounting as a system for planning, control, learning, and strategic action. Explain how internal accounting information differs from external reporting and how managers use it to make better decisions.", "children": [{"id": "86e2d8db-6e62-4d6d-ae14-58ece5014284", "type": "subtopic", "title": "Internal versus external reporting", "children": [{"id": "a25ec287-a25a-427c-818f-b23ec342d97d", "type": "concept", "title": "internal user"}, {"id": "64e96923-e828-4ca7-a928-d4c9e73a00a9", "type": "concept", "title": "external user"}, {"id": "36079a7f-4ec0-405e-8b39-79598e7473a3", "type": "concept", "title": "decision relevance"}, {"id": "652e402e-6d3e-40fa-b383-3650f342cdc1", "type": "concept", "title": "timeliness"}, {"id": "3a60a62a-0aa9-4e07-9ee3-ecaea97c2ecb", "type": "concept", "title": "level of detail"}, {"id": "c5250ce5-4b9b-4ce3-a152-294bdf4579bc", "type": "concept", "title": "segment view"}, {"id": "7078c404-9c07-423f-8356-0c8b73b04894", "type": "concept", "title": "prospective information"}, {"id": "d92b33de-ecbe-4906-b6a1-c82c5e63ffd5", "type": "concept", "title": "nonfinancial measure"}, {"id": "e29b8063-d9f0-42b5-b370-278c1c83ace0", "type": "concept", "title": "controllability"}, {"id": "f30f0e9a-4645-4ad1-bc0b-bf1fe8ba5dd9", "type": "concept", "title": "behavioral consequence"}], "description": "Students learn why managerial accounting is built around relevance, timeliness, and decision usefulness rather than GAAP compliance alone."}, {"id": "483805d3-d834-49cd-a513-0ff7b8e263f8", "type": "subtopic", "title": "Planning, control, and feedback loops", "children": [{"id": "01cc6408-e56a-41c8-9c6e-7fe9ccadb0d0", "type": "concept", "title": "planning"}, {"id": "1a25274a-dec7-4dab-a2d4-7901899821be", "type": "concept", "title": "operating control"}, {"id": "8e90e3c5-1683-4f12-9df9-45d0891f5e00", "type": "concept", "title": "management control"}, {"id": "7fa45f31-b407-4b23-9aa6-9a9aeab45fc1", "type": "concept", "title": "feedback control"}, {"id": "7838c5f9-d60b-4eb3-b0c1-49a37d66d858", "type": "concept", "title": "feedforward control"}, {"id": "a295a150-f3e1-4e29-ad25-ccd610d06c7c", "type": "concept", "title": "budget cycle"}, {"id": "3860943e-b1a2-402a-a5e7-b221d73b5c60", "type": "concept", "title": "performance report"}, {"id": "bdf52254-7842-4d79-a8f5-77c3006c35b7", "type": "concept", "title": "variance signal"}, {"id": "5cdc54c3-526a-4221-8afa-9d5acd7d72c8", "type": "concept", "title": "corrective action"}, {"id": "ac1089a7-217d-40aa-a9d3-be510e76e22f", "type": "concept", "title": "learning loop"}], "description": "This subtopic introduces management accounting as an operating rhythm: plan, execute, measure, learn, and revise."}, {"id": "d3402694-5f9b-4ab3-a103-b8e6df9c3748", "type": "subtopic", "title": "Decision context and information quality", "children": [{"id": "d2d0db53-22c5-45c1-8fea-12f8b8fba6cf", "type": "concept", "title": "accuracy"}, {"id": "0e21a01e-f3b4-4e80-a86d-0e881d936625", "type": "concept", "title": "precision"}, {"id": "b097a833-bed5-4bad-a2cc-58a4908896fc", "type": "concept", "title": "relevance"}, {"id": "3f5489ee-7cf7-46ac-af90-b7c289c3d27e", "type": "concept", "title": "reliability"}, {"id": "8fce803c-ad49-47eb-a351-c69c07a2533e", "type": "concept", "title": "timeliness"}, {"id": "9448d158-a13e-4c33-9ea3-e6fef0bdedf7", "type": "concept", "title": "cost-benefit tradeoff"}, {"id": "2703b12d-dafc-43d0-84b6-637480c29f46", "type": "concep