ic", "title": "Cost objects and assignment", "children": [{"id": "cc4d5eaf-8628-4775-8c10-8f3d2ae69e18", "type": "concept", "title": "cost object"}, {"id": "7b1704a9-4928-49c9-b9ce-bab89e042a11", "type": "concept", "title": "cost pool"}, {"id": "ff0b5e39-6140-4094-81bc-9fadd73ce2e7", "type": "concept", "title": "cost allocation"}, {"id": "2b347d07-821d-47f1-bf75-df9b29137977", "type": "concept", "title": "cost tracing"}, {"id": "c40c2eeb-80d3-4d37-a709-74cd9bc1122e", "type": "concept", "title": "cost driver"}, {"id": "35cd763b-d3fa-47bb-926a-1ee333d10211", "type": "concept", "title": "allocation base"}, {"id": "9bb0f5ff-8ed9-4d2b-8ebf-e03cd333b9c3", "type": "concept", "title": "cost accumulation"}, {"id": "79149f03-690f-4366-9e0b-451005a57efe", "type": "concept", "title": "cost assignment"}, {"id": "5ab38f24-c8b3-4adf-9b47-2d2f4053943c", "type": "concept", "title": "cost hierarchy"}, {"id": "4b94996b-b959-486a-b353-514efd7725ce", "type": "concept", "title": "common cost"}], "description": "This section explains what is being costed and how cost information attaches to it."}, {"id": "dcd59727-bb0c-474b-89a4-4df7744e4493", "type": "subtopic", "title": "Cost behavior foundations", "children": [{"id": "02b21a7f-64df-4319-905c-1527ae553484", "type": "concept", "title": "variable cost"}, {"id": "de02b0c4-4815-475e-b4a5-8f1e2be5faa3", "type": "concept", "title": "fixed cost"}, {"id": "580606ff-d873-4aa2-adcd-3159815a89c5", "type": "concept", "title": "mixed cost"}, {"id": "3f37cd24-2a85-4164-a34d-046be604aeb0", "type": "concept", "title": "step cost"}, {"id": "0a89f565-bfbc-477c-8433-6d145c5fe613", "type": "concept", "title": "relevant range"}, {"id": "09c61af7-5cfd-47bd-859a-0197c1386902", "type": "concept", "title": "capacity cost"}, {"id": "f9952cef-cdca-4ee2-b36a-e6c18b049f77", "type": "concept", "title": "committed cost"}, {"id": "4a4d4dce-2aa7-401f-b19b-4c5bc7cc9712", "type": "concept", "title": "discretionary cost"}, {"id": "677e87b7-362a-458d-89ad-b28a44c1910d", "t