", "title": "idle capacity"}, {"id": "2a57a4b0-d94e-4795-aa38-c5f025568e9e", "type": "concept", "title": "unused capacity"}, {"id": "be7c2c8a-403e-4fbd-958b-05c0e65b0017", "type": "concept", "title": "bottleneck capacity"}, {"id": "682d1f87-681c-4090-8b1c-e5ce024c4c5d", "type": "concept", "title": "capacity cost rate"}, {"id": "9dcc4ff4-bebb-4169-aee5-00d0c011a7d3", "type": "concept", "title": "resource commitment"}], "description": "This section gives students vocabulary for measuring and managing unused resources."}, {"id": "67b215bd-b5c8-47eb-9a69-4b21886f5339", "type": "subtopic", "title": "Behavioral and reporting implications", "children": [{"id": "abeaa7f9-5c9e-4a12-bb97-a7663aa23adc", "type": "concept", "title": "overproduction incentive"}, {"id": "a91ad1e2-f33f-4b79-b071-f9fc5f4869d0", "type": "concept", "title": "inventory buildup"}, {"id": "ec959940-b87e-4d59-a163-1b72fa5f661d", "type": "concept", "title": "earnings management"}, {"id": "c6ce5ab5-a1be-481c-bd8d-d784aafa9af1", "type": "concept", "title": "throughput focus"}, {"id": "754b175c-40e2-4e37-9c16-b2addce9128e", "type": "concept", "title": "cost absorption"}, {"id": "608d923e-b965-4176-913c-a1cceb87f5e7", "type": "concept", "title": "performance metric design"}, {"id": "0b746e8c-82bd-4ab1-bb6b-e0521c3a3430", "type": "concept", "title": "manager bonus"}, {"id": "81bd6203-c017-42bd-bec7-fb3e25d8a1ca", "type": "concept", "title": "production smoothing"}, {"id": "f9e9ab52-0773-4f5a-8ac9-e5bbe20a9043", "type": "concept", "title": "stockout risk"}, {"id": "bf9c190c-87a6-446c-8251-de8df5cd8cd6", "type": "concept", "title": "ethical implication"}], "description": "Students learn how costing method choices can influence production decisions."}]}, {"id": "b7e8f6f6-1f01-4662-b6d4-87f011d1f6ce", "type": "topic", "title": "Budgeting, Forecasting, and Responsibility Accounting", "description": "Use budgets as planning, coordination, communication, and accountability tools. Prepare operating budgets and connect budget design to responsibility centers and managerial behavior.", "children": [{"id": "0ee454a3-f706-473a-ba41-5665a64307a0", "type": "subtopic", "title": "Master budget components", "children": [{"id": "dac3fd41-ee4b-4a42-b249-ba9f2845f422", "type": "concept", "title": "sales budget"}, {"id": "10da34e9-1fd9-4bbf-9cc2-316614cd84fb", "type": "concept", "title": "production budget"}, {"id": "a01c4c40-3b0f-4e25-90e8-4103aa46f422", "type": "concept", "title": "direct materials budget"}, {"id": "a5f3ec58-f9f9-4012-b202-4e81df0481b1", "type": "concept", "title": "direct labor budget"}, {"id": "ff4ed5c7-e08e-4a39-a53e-64b25c9c82db", "type": "concept", "title": "manufacturing overhead budget"}, {"id": "0ff1826a-abbf-4d9b-b60f-ab5c37b69f0e", "type": "concept", "title": "selling and administrative budget"}, {"id": "3738473f-75e4-488d-807b-6a1d62d45adc", "type": "concept", "title": "cash budget"}, {"id": "6a2572b1-e1cb-4ddb-b086-b3edcfe59558", "type": "concept", "title": "budgeted income statement"}, {"id": "54be5501-083d-4bc3-b5c1-ca48cc4a430a", "type": "concept", "title": "budgeted balance sheet"}, {"id": "451e0d89-89e3-4a92-a958-d8b98f70e0b0", "type": "concept", "title": "budgeted cash flows"}], "description": "Students learn how operating and financial budgets fit together."}, {"id": "d8c71d36-6c7c-4494-aea2-5a01ecad4c53", "type": "subtopic", "title": "Forecasting and rolling planning", "children": [{"id": "aa33c26a-55a3-44a6-905a-78f21ae3ed83", "type": "concept", "title": "rolling forecast"}, {"id": "54411591-f8a4-4e80-aa3b-ed651ab1e3ed", "type": "concept", "title": "driver-based forecast"}, {"id": "21aeacb0-6758-4c15-97fc-b83fbb13d8b7", "type": "concept", "title": "scenario planning"}, {"id": "3b87c980-1e78-43fa-9c1d-132f799787c4", "type": "concept", "title": "forecast horizon"}, {"id": "cf97d801-48b0-4fe6-9cb7-a6773fe1f1f8", "type": "concept", "title": "demand forecast"}, {"id": "a36f5e07-7e82-4a66-bafa-9662db90d4a4", "type": "concept", "title": "price forecast"}, {"id